const COLORS = {
  iron: ['#505a64', '#7d8991', '#a9b4b9', '#d5dcda', '#e9ebe2'],
  gold: ['#775333', '#a67c3e', '#c8a456', '#e2c783', '#efe0ad'],
  copper: ['#754a3e', '#9b624b', '#bd8764', '#d8af87', '#ead0aa'],
  diamond: ['#295359', '#3c7c82', '#65aaad', '#9bd3cf', '#c8e5da'],
  netherite: ['#29282f', '#3c3944', '#57515c', '#79717a', '#aaa097'],
  chainmail: ['#424a50', '#69747b', '#939fa3', '#bbc6c4', '#d7dbd2'],
  // Grayscale preserves the game's multiplicative leather dye behaviour.
  leather: ['#646464', '#858585', '#a7a7a7', '#c9c9c9', '#dedede'],
  leather_overlay: ['#4f3b2b', '#765638', '#9e7950', '#c3a371', '#d3be91'],
  turtle: ['#344733', '#526741', '#7c8f54', '#a6b570', '#c5ca91'],
  elytra: ['#363641', '#515262', '#717487', '#9599a8', '#bdc1c6'],
};

function versionTuple(version) {
  if (typeof version !== 'string' || !/^\d+(?:\.\d+){1,2}$/.test(version)) throw new TypeError('equipment.files needs a release version string');
  return version.split('.').map(Number);
}
function compare(a, b) {
  for (let i = 0; i < 3; i++) { const d = (a[i] || 0) - (b[i] || 0); if (d) return d; }
  return 0;
}
function boxFaces(u, v, w, h, d, part) {
  return [
    [u + d, v, w, d, part, 'top'], [u + d + w, v, w, d, part, 'bottom'],
    [u, v + d, d, h, part, 'side'], [u + d, v + d, w, h, part, 'front'],
    [u + d + w, v + d, d, h, part, 'side'], [u + 2 * d + w, v + d, w, h, part, 'back'],
  ];
}
function facesFor(path) {
  if (path.includes('elytra')) return boxFaces(22, 0, 10, 20, 2, 'wing');
  if (path.includes('humanoid_baby/')) {
    // 26.1 HumanoidModel.createBabyArmorMesh (javap), NOT BabyZombieModel:
    // head 9x8x8, chest 6x5x3, arms 2x5x3, legs/feet independently mapped.
    return [
      ...boxFaces(0, 0, 9, 8, 8, 'head'), ...boxFaces(0, 17, 6, 5, 3, 'body'),
      ...boxFaces(0, 36, 6, 2, 3, 'waist'), ...boxFaces(30, 25, 2, 5, 3, 'arm'),
      ...boxFaces(30, 17, 2, 5, 3, 'arm'), ...boxFaces(18, 24, 3, 4, 3, 'leg'),
      ...boxFaces(18, 17, 3, 4, 3, 'leg'), ...boxFaces(0, 25, 3, 1, 3, 'foot'),
      ...boxFaces(0, 29, 3, 1, 3, 'foot'),
    ];
  }
  return [
    ...boxFaces(0, 0, path.includes('piglin_') ? 10 : 8, 8, 8, 'head'),
    ...boxFaces(16, 16, 8, 12, 4, 'body'), ...boxFaces(0, 16, 4, 12, 4, 'leg'),
    ...boxFaces(40, 16, 4, 12, 4, 'arm'),
  ];
}

function materialFor(path) {
  if (path.includes('elytra')) return 'elytra';
  if (path.includes('overlay')) return 'leather_overlay';
  if (path.includes('turtle')) return 'turtle';
  return ['chainmail', 'netherite', 'diamond', 'copper', 'leather', 'iron', 'gold'].find((m) => path.includes(m));
}
const clamp = (v) => Math.max(0, Math.min(4, v));

function shade(face, x, y, material, k) {
  const [u, v, w, h, part, side] = face;
  const fx = (x - u * k), fy = (y - v * k);
  const W = w * k, H = h * k;
  const nx = fx / Math.max(1, W - 1), ny = fy / Math.max(1, H - 1);
  const top = fy < k, bottom = fy >= H - k;
  const left = fx < k, right = fx >= W - k;
  let level = side === 'top' ? 3 : side === 'bottom' || side === 'back' ? 1 : 2;
  if (material === 'chainmail') {
    // Holes come exclusively from the measured mask. This alternating wire
    // light changes the link direction without filling even one cutout pixel.
    return (Math.floor(x / k) + Math.floor(y / k)) % 2 ? 1 + ((x + y) % k === 0 ? 1 : 0) : 3;
  }
  if (material === 'leather_overlay') {
    return top || left ? 3 : bottom || right ? 1 : 2;
  }
  if (material === 'leather') {
    level = side === 'top' ? 3 : side === 'bottom' ? 1 : 2;
    if (left || right || bottom) level = 1; // welt
    if ((fx === k || fx === W - k - 1) && Math.floor(fy / k) % 3 === 1) level = 3; // stitching
    if (part === 'body' && ny > 0.68 && ny < 0.82) level = 1; // sewn waist panel
    if (k > 1 && !left && !right && (x * 17 + y * 11) % 43 === 0) level = 3;
    return level;
  }
  if (material === 'turtle') {
    // Broad overlapping scutes, low-contrast seams. Olive rather than neon.
    const sx = Math.floor(fx / (3 * k)), sy = Math.floor(fy / (3 * k));
    const seam = fy % (3 * k) === 0 || (fx + (sy % 2) * k) % (4 * k) === 0;
    return seam ? 1 : clamp(2 + ((sx + sy) % 3 === 0 ? 1 : 0) + (side === 'top' ? 1 : 0));
  }
  if (material === 'elytra') {
    // Indigo-grey flight membrane, reinforced leading edge and sparse ribs.
    const rib = Math.abs(fx - (Math.floor(fy / (5 * k)) * 2 * k + 2 * k)) < k;
    return left || bottom ? 1 : rib ? 3 : clamp(2 + (nx < 0.32 ? 1 : 0) - (ny > 0.75 ? 1 : 0));
  }
  if (top || left) level = 3;
  if (bottom || right) level = 1;
  // Rolled plate edges have a darker inner seam, never a black outline.
  if (k > 1 && (fy === k || fx === W - k - 1) && W >= 6) level = 1;
  if (part === 'body' && side === 'front') {
    // Each material has its own construction, not the same armour recoloured.
    if (material === 'iron') {
      if (Math.abs(nx - 0.5) < 0.12 && ny < 0.7) level = 3; // raised sternum
      if (ny > 0.73 && ny < 0.83) level = 1; // articulated fauld
    } else if (material === 'gold') {
      if (ny > 0.18 && ny < 0.3 && nx > 0.12 && nx < 0.88) level = 1; // inset collar
      if (ny > 0.62 && ny < 0.73) level = 3;
    } else if (material === 'diamond') {
      const diagonal = Math.abs(nx - 0.5) * 0.7 + 0.22;
      if (Math.abs(ny - diagonal) < 0.08) level = 3; // angular crystalline yoke
      if (ny > 0.7 && nx > 0.25 && nx < 0.75) level = 1;
    } else if (material === 'netherite') {
      if (ny > 0.23 && ny < 0.34) level = 1;
      if ((nx < 0.25 || nx > 0.75) && ny < 0.62) level = 3; // heavy side plates
    } else if (material === 'copper') {
      if (ny > 0.38 && ny < 0.48) level = 1;
      if (Math.abs(nx - 0.5) < 0.1 && ny > 0.24) level = 3;
    }
  }
  if (part === 'arm' && ny > 0.34 && ny < 0.45) level = material === 'diamond' ? 3 : 1;
  if (part === 'leg' && ny > 0.59 && ny < 0.7) level = material === 'netherite' ? 3 : 1;
  if (part === 'head' && side === 'front' && ny > 0.24 && ny < 0.4) level = 3;
  // Narrow brushed highlights in the higher-resolution edition only.
  if (k > 1 && level === 3 && fx === k && fy > k && fy < H * 0.6) level = 4;
  return clamp(level);
}

function paint(path, maskId, style) {
  const [w, h, rows] = UV_DATA.masks[maskId];
  const bits = rows.map((row) => BigInt(`0x${row}`));
  const k = style === 'looks' ? 2 : 1;
  const image = new Image(w * k, h * k);
  const material = materialFor(path), pal = COLORS[material].map(rgba);
  const faces = facesFor(path);
  const mask = (x, y) => x >= 0 && y >= 0 && x < w && y < h && !!(bits[y] & (1n << BigInt(x)));
  for (let y = 0; y < image.h; y++) for (let x = 0; x < image.w; x++) {
    const sx = Math.floor(x / k), sy = Math.floor(y / k);
    if (!mask(sx, sy)) continue;
    const face = faces.find(([u, v, fw, fh]) => x >= u * k && y >= v * k && x < (u + fw) * k && y < (v + fh) * k);
    let level = face ? shade(face, x, y, material, k) : 2;
    // Shade silhouette bevels as well as UV seams, but never change alpha.
    if (material !== 'chainmail' && material !== 'leather_overlay') {
      if (!mask(sx, sy + 1)) level = Math.min(level, 1);
      else if (!mask(sx, sy - 1)) level = Math.max(level, 3);
    }
    image.set(x, y, pal[level]);
  }
  return image;
}

function files(mcVersion, style) {
  const version = versionTuple(mcVersion);
  if (!['fast', 'looks'].includes(style)) throw new TypeError('equipment.files style must be fast or looks');
  const paths = new Map();
  for (const revision of UV_DATA.revisions) {
    if (compare(version, versionTuple(revision.since)) < 0) break;
    for (const path of revision.remove || []) paths.delete(path);
    for (const [path, mask] of Object.entries(revision.add)) paths.set(path, mask);
  }
  return [...paths].map(([path, mask]) => [path, paint(path, mask, style)]);
}

module.exports = { files };
